;(()=>{
  let _devPass = '';
  let _devMode = 'auto';
  let _devPlan = 'سنوي';
  let _devLastCode = '';

  function devTodayPlus(days){
    const d = new Date(Date.now() + days * 86400000);
    return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
  }

  function devRenderHist(list){
    const box = document.getElementById('devHistBox');
    const ul = document.getElementById('devHist');
    if(!box || !ul) return;
    if(!Array.isArray(list) || !list.length){ box.hidden = true; ul.innerHTML = ''; return; }
    box.hidden = false;
    ul.innerHTML = '';
    list.forEach(item => {
      const row = document.createElement('div');
      row.className = 'dev-hi';
      const info = document.createElement('div');
      const b = document.createElement('b');
      b.textContent = item.id || '';
      const sp = document.createElement('span');
      sp.textContent = ' · ' + (item.plan || '') + ' · ' + (item.papers || '') + ' · ' + (item.exp || '');
      info.appendChild(b);
      info.appendChild(sp);
      const cp = document.createElement('button');
      cp.type = 'button';
      cp.className = 'minib';
      cp.textContent = tr('نسخ الكود');
      cp.onclick = () => {
        navigator.clipboard?.writeText(item.code).then(()=>toast(tr('تم نسخ الكود ✓'))).catch(()=>{});
      };
      row.appendChild(info);
      row.appendChild(cp);
      ul.appendChild(row);
    });
  }

  window.openDev = function(){
    const m = document.getElementById('devM');
    if(!m) return;
    document.getElementById('devLockErr').textContent = '';
    document.getElementById('devGenErr').textContent = '';
    const locked = !_devPass;
    document.getElementById('devLockBox').hidden = !locked;
    document.getElementById('devPanelBox').hidden = locked;
    m.classList.add('op');
    if(locked){
      const inp = document.getElementById('devPassIn');
      inp.value = '';
      setTimeout(()=>inp.focus(), 60);
    } else {
      fetch('/api/dev/list', {
        method:'POST',
        headers:{'content-type':'application/json'},
        body:JSON.stringify({password:_devPass})
      }).then(r=>r.ok?r.json():null).then(j=>{ if(j&&j.ok) devRenderHist(j.history); }).catch(()=>{});
    }
  };

  window.devUnlock = async function(){
    const inp = document.getElementById('devPassIn');
    const err = document.getElementById('devLockErr');
    const btn = document.getElementById('devUnlBtn');
    const pass = inp.value || '';
    err.textContent = '';
    if(!pass){ err.textContent = tr('كلمة المرور غير صحيحة'); inp.focus(); return; }
    btn.disabled = true;
    try{
      const r = await fetch('/api/dev/verify', {
        method:'POST',
        headers:{'content-type':'application/json'},
        body:JSON.stringify({password:pass})
      });
      const j = await r.json().catch(()=>null);
      if(!r.ok || !j || !j.ok){
        err.textContent = tr('كلمة المرور غير صحيحة');
        inp.select();
        return;
      }
      _devPass = pass;
      document.getElementById('devLockBox').hidden = true;
      document.getElementById('devPanelBox').hidden = false;
      const expEl = document.getElementById('devExp');
      if(expEl && !expEl.value) expEl.value = devTodayPlus(365);
      fetch('/api/dev/list', {
        method:'POST',
        headers:{'content-type':'application/json'},
        body:JSON.stringify({password:_devPass})
      }).then(r2=>r2.ok?r2.json():null).then(j2=>{ if(j2&&j2.ok) devRenderHist(j2.history); }).catch(()=>{});
    } catch {
      err.textContent = tr('تعذر الاتصال بالخادم');
    } finally {
      btn.disabled = false;
    }
  };

  window.devLock = function(){
    _devPass = '';
    _devLastCode = '';
    document.getElementById('devOut').hidden = true;
    document.getElementById('devPanelBox').hidden = true;
    document.getElementById('devLockBox').hidden = false;
    const inp = document.getElementById('devPassIn');
    inp.value = '';
    setTimeout(()=>inp.focus(), 50);
  };

  window.devSetMode = function(mode){
    _devMode = mode === 'manual' ? 'manual' : 'auto';
    document.getElementById('devTabAuto').classList.toggle('on', _devMode === 'auto');
    document.getElementById('devTabManual').classList.toggle('on', _devMode === 'manual');
    document.getElementById('devIdWrap').hidden = _devMode === 'auto';
    document.getElementById('devExpWrap').hidden = _devMode === 'auto';
    document.getElementById('devDaysWrap').hidden = _devMode === 'manual';
    document.getElementById('devGenBtn').textContent = tr(_devMode === 'manual' ? 'إنشاء كود يدوي' : 'إنشاء كود تلقائي');
    if(_devMode === 'manual'){
      const d = Math.max(1, parseInt(document.getElementById('devDays').value || '30', 10) || 30);
      document.getElementById('devExp').value = devTodayPlus(d);
    }
  };

  window.devPickPlan = function(plan, days, papers, btn){
    _devPlan = plan;
    document.querySelectorAll('#devM .dev-pl').forEach(b=>b.classList.remove('on'));
    if(btn) btn.classList.add('on');
    document.getElementById('devDays').value = String(days);
    document.getElementById('devPapers').value = String(papers);
    document.getElementById('devExp').value = devTodayPlus(days);
  };

  window.devGen = async function(){
    if(!_devPass){ window.devLock(); return; }
    const err = document.getElementById('devGenErr');
    const btn = document.getElementById('devGenBtn');
    err.textContent = '';
    const days = parseInt(document.getElementById('devDays').value || '30', 10) || 30;
    const papers = parseInt(document.getElementById('devPapers').value || '40', 10) || 40;
    const body = {
      password: _devPass,
      mode: _devMode,
      plan: _devPlan,
      days,
      papers,
      codeId: document.getElementById('devCodeId').value.trim(),
      exp: document.getElementById('devExp').value
    };
    btn.disabled = true;
    try{
      const r = await fetch('/api/dev/generate', {
        method:'POST',
        headers:{'content-type':'application/json'},
        body:JSON.stringify(body)
      });
      const j = await r.json().catch(()=>null);
      if(r.status === 401){ window.devLock(); return; }
      if(!r.ok || !j || !j.ok){ err.textContent = tr('تعذر الاتصال بالخادم'); return; }
      _devLastCode = j.code;
      document.getElementById('devOut').hidden = false;
      document.getElementById('devOutCode').textContent = j.code;
      document.getElementById('devOutMeta').textContent = (j.payload.id || '') + ' · ' + tr(j.payload.plan || '') + ' · ' + j.payload.papers + ' · ' + j.payload.exp;
      devRenderHist(j.history || []);
    } catch {
      err.textContent = tr('تعذر الاتصال بالخادم');
    } finally {
      btn.disabled = false;
    }
  };

  window.devCopy = function(){
    if(!_devLastCode) return;
    navigator.clipboard?.writeText(_devLastCode).then(()=>toast(tr('تم نسخ الكود ✓'))).catch(()=>toast(tr('تعذر النسخ')));
  };

  window.devActivate = async function(){
    if(!_devLastCode) return;
    const lic = await verifyLic(_devLastCode);
    if(!lic){ toast(tr('الكود غير صحيح — تأكد أنك نسخته كاملا')); return; }
    const onLock = document.body.classList.contains('show-lock');
    if(onLock){
      const cin = document.getElementById('cin');
      if(cin) cin.value = _devLastCode;
      const tc = document.getElementById('tcAccept');
      if(tc) tc.checked = true;
      cm('devM');
      await tryAct();
    } else {
      const ac = document.getElementById('acCode');
      if(ac) ac.value = _devLastCode;
      await activateCode('a');
      cm('devM');
      toast(tr('مفعل ✓'));
    }
  };

  window.devWhatsApp = function(){
    if(!_devLastCode) return;
    waOpen('كود تفعيل برهم:\n' + _devLastCode);
  };
})();

(function(){
  let _lastSolveText = '';
  let _solving = false;

  function cleanTxt(v){
    if(v == null) return '';
    const str = String(v);
    if(str.indexOf('<') === -1) return str.trim();
    const d = document.createElement('div');
    d.innerHTML = str;
    return (d.textContent || d.innerText || '').trim();
  }

  function syncSolveOnline(){
    const btn = document.getElementById('solvebtn');
    if(!btn) return;
    const online = typeof navigator === 'undefined' ? true : navigator.onLine !== false;
    btn.classList.toggle('off', !online);
  }

  window.addEventListener('online', syncSolveOnline);
  window.addEventListener('offline', syncSolveOnline);
  window.addEventListener('DOMContentLoaded', syncSolveOnline);

  function showSolveErr(title, detail, canRetry){
    const load = document.getElementById('solveLoad');
    const res = document.getElementById('solveRes');
    const err = document.getElementById('solveErr');
    const foot = document.getElementById('solveFoot');
    if(load) load.hidden = true;
    if(res) res.hidden = true;
    if(foot) foot.hidden = true;
    if(!err) return;
    err.hidden = false;
    err.innerHTML = '';
    const b = document.createElement('b');
    b.textContent = title;
    const p = document.createElement('div');
    p.textContent = detail;
    err.appendChild(b);
    err.appendChild(p);
    if(canRetry){
      const rb = document.createElement('button');
      rb.type = 'button';
      rb.className = 'mbtn bpr';
      rb.style.marginTop = '10px';
      rb.textContent = tr('حاول مرة أخرى');
      rb.onclick = function(){ window.solveAllQ(); };
      err.appendChild(rb);
    }
  }

  window.copySolveAll = function(){
    if(!_lastSolveText) return;
    navigator.clipboard?.writeText(_lastSolveText)
      .then(()=>toast(tr('تم نسخ جميع الحلول ✓')))
      .catch(()=>toast(tr('تعذر النسخ')));
  };

  window.solveAllQ = async function(){
    if(_solving) return;
    syncSolveOnline();

    const m = document.getElementById('solveM');
    const load = document.getElementById('solveLoad');
    const err = document.getElementById('solveErr');
    const res = document.getElementById('solveRes');
    const sum = document.getElementById('solveSum');
    const list = document.getElementById('solveList');
    const foot = document.getElementById('solveFoot');
    const btn = document.getElementById('solvebtn');

    if(m && !m.classList.contains('op')){
      m.classList.add('op');
    }

    if(typeof navigator !== 'undefined' && navigator.onLine === false){
      showSolveErr(tr('غير متصل بالإنترنت'), tr('اتصل بالإنترنت أولاً لاستخدام الحل التلقائي للأسئلة.'), true);
      return;
    }

    const payloadQuestions = (Array.isArray(qs) ? qs : []).map((q)=>({
      topic: cleanTxt(q && q.topic),
      grade: cleanTxt(q && q.grade),
      body: cleanTxt(q && q.body),
      parts: (q && Array.isArray(q.parts) ? q.parts : []).map((p)=>({
        kind: p && p.kind ? String(p.kind) : 'text',
        text: cleanTxt(p && p.text),
        grade: cleanTxt(p && p.grade),
        opts: p && Array.isArray(p.opts) ? p.opts.map(cleanTxt) : [],
        items: p && Array.isArray(p.items) ? p.items.map((it)=>({ text: cleanTxt(it && it.text) })) : [],
        pairs: p && Array.isArray(p.pairs) ? p.pairs.map((pr)=>({ a: cleanTxt(pr && pr.a), b: cleanTxt(pr && pr.b) })) : [],
        extra: p && Array.isArray(p.extra) ? p.extra.map(cleanTxt) : []
      }))
    }));

    const hasAnyContent = payloadQuestions.some((q)=>
      q.topic || q.body || q.parts.some((p)=>
        p.text || p.opts.some(Boolean) || p.items.some((it)=>it.text) || p.pairs.some((pr)=>pr.a || pr.b)
      )
    );

    if(!hasAnyContent){
      showSolveErr(tr('حل الأسئلة تلقائياً'), tr('أضف سؤالاً واكتب نصه أولاً ثم اضغط حل الأسئلة تلقائياً.'), false);
      return;
    }

    _solving = true;
    if(btn) btn.disabled = true;
    if(err) err.hidden = true;
    if(res) res.hidden = true;
    if(foot) foot.hidden = true;
    if(load) load.hidden = false;

    try{
      const r = await fetch('/api/solve', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
          title: cleanTxt(vv('f-title')),
          subject: cleanTxt(vv('f-subject')),
          grade: cleanTxt(vv('f-grade')),
          paperLang: vv('f-lang') || 'ar',
          uiLang: typeof UIL === 'string' ? UIL : 'ar',
          questions: payloadQuestions
        })
      });
      const j = await r.json().catch(()=>null);
      if(!r.ok || !j || !j.ok){
        const detail = (j && j.msg) ? String(j.msg) : tr('تعذر الاتصال بالخادم');
        showSolveErr(tr('تعذر حل الأسئلة حالياً'), detail, true);
        return;
      }

      if(load) load.hidden = true;
      if(err) err.hidden = true;
      if(res) res.hidden = false;
      if(foot) foot.hidden = false;

      if(sum){
        if(j.summary){
          sum.textContent = j.summary;
          sum.hidden = false;
        } else {
          sum.hidden = true;
        }
      }

      if(list){
        list.innerHTML = '';
        const allLines = [];
        if(j.summary) allLines.push(j.summary);
        (j.solutions || []).forEach((sol, idx)=>{
          const qNum = sol && sol.qNum ? sol.qNum : (idx + 1);
          const title = (sol && sol.title) ? String(sol.title) : (tr('السؤال ') + qNum);
          const ans = (sol && sol.answer) ? String(sol.answer) : '';
          const steps = (sol && sol.steps) ? String(sol.steps).trim() : '';

          const card = document.createElement('div');
          card.className = 'solve-card';

          const ch = document.createElement('div');
          ch.className = 'solve-ch';
          const b = document.createElement('b');
          b.textContent = title;
          const cp = document.createElement('button');
          cp.type = 'button';
          cp.className = 'solve-cp';
          cp.textContent = tr('نسخ الحل');
          const oneText = [title, ans, steps].filter(Boolean).join('\n');
          cp.onclick = function(){
            navigator.clipboard?.writeText(oneText)
              .then(()=>toast(tr('تم نسخ الحل ✓')))
              .catch(()=>toast(tr('تعذر النسخ')));
          };
          ch.appendChild(b);
          ch.appendChild(cp);
          card.appendChild(ch);

          const ansEl = document.createElement('div');
          ansEl.className = 'solve-ans';
          ansEl.textContent = ans;
          card.appendChild(ansEl);

          if(steps){
            const stEl = document.createElement('div');
            stEl.className = 'solve-steps';
            stEl.textContent = steps;
            card.appendChild(stEl);
          }

          list.appendChild(card);
          allLines.push(oneText);
        });
        _lastSolveText = allLines.join('\n\n');
      }
    } catch {
      showSolveErr(tr('تعذر حل الأسئلة حالياً'), tr('تعذر الاتصال بالخادم'), true);
    } finally {
      _solving = false;
      if(btn) btn.disabled = false;
    }
  };
})();

(function(){try{if(!SLS.getItem('_smqblk')){if(typeof ss==='object'&&ss&&(ss.qc==='#0369a1'||!ss.qc)){ss.qc='#000000';if(typeof fmtSync==='function')fmtSync();if(typeof up==='function')up();if(typeof saveSess==='function')saveSess();}SLS.setItem('_smqblk','1');}}catch{}})();

(function(){
  let _micOn = false;
  let _rec = null;
  let _committedIdx = 0;
  let _lastTarget = null;
  let _fallbackMode = false;
  let _mediaRec = null;
  let _mediaStream = null;
  let _mediaChunks = [];
  let _chunkTimer = null;

  document.addEventListener('focusin', function(e){
    const t = e.target;
    if(!t || !t.closest) return;
    const ql = document.getElementById('ql');
    if(ql && ql.contains(t) && (t.classList.contains('rte') || t.tagName === 'TEXTAREA' || (t.tagName === 'INPUT' && t.type !== 'number'))){
      _lastTarget = t;
    }
  });

  function focusEnd(el){
    if(!el) return;
    try{ el.focus({ preventScroll: false }); }catch{ try{ el.focus(); }catch{} }
    if(el.classList && el.classList.contains('rte')){
      try{
        const m = rtM(el.dataset.rt);
        const len = m ? (m.get().text || '').length : (el.textContent || '').length;
        rtSetSel(el, len, len);
      }catch{}
    } else if(typeof el.value === 'string' && typeof el.setSelectionRange === 'function'){
      const len = el.value.length;
      try{ el.setSelectionRange(len, len); }catch{}
    }
    _lastTarget = el;
  }

  function ensureTarget(){
    const ql = document.getElementById('ql');
    const act = document.activeElement;
    if(ql && act && ql.contains(act) && (act.classList.contains('rte') || act.tagName === 'TEXTAREA' || (act.tagName === 'INPUT' && act.type !== 'number'))){
      _lastTarget = act;
      return act;
    }
    if(_lastTarget && document.contains(_lastTarget) && ql && ql.contains(_lastTarget)){
      focusEnd(_lastTarget);
      return _lastTarget;
    }
    if(Array.isArray(qs) && qs.length === 0){
      addQ('normal');
    }
    const cards = ql ? ql.querySelectorAll('.qc') : [];
    for(let i = cards.length - 1; i >= 0; i--){
      const card = cards[i];
      if(card.classList.contains('op')){
        const box = card.querySelector('.qbd, .pta, textarea.fi');
        if(box){ focusEnd(box); return box; }
      }
    }
    if(cards.length > 0){
      const lastIdx = cards.length - 1;
      if(typeof qFold === 'function') qFold(lastIdx);
      const box = cards[lastIdx].querySelector('.qbd, .pta, textarea.fi');
      if(box){ focusEnd(box); return box; }
    }
    return null;
  }

  function getFieldTextBefore(el){
    if(!el) return '';
    if(el.classList && el.classList.contains('rte')){
      try{
        const m = rtM(el.dataset.rt);
        const sel = rtSel(el);
        const txt = m ? (m.get().text || '') : '';
        return sel ? txt.slice(0, sel[0]) : txt;
      }catch{ return el.textContent || ''; }
    }
    if(typeof el.value === 'string'){
      const pos = typeof el.selectionStart === 'number' ? el.selectionStart : el.value.length;
      return el.value.slice(0, pos);
    }
    return '';
  }

  function insertRaw(raw){
    if(!raw) return;
    const el = ensureTarget();
    if(!el) return;

    let txt = String(raw);
    if(txt !== '\n'){
      const before = getFieldTextBefore(el);
      if(before && !/[\s\n(«"']$/.test(before) && !/^[\s\n.,،؛:؟?!…)»"']/.test(txt)){
        txt = ' ' + txt;
      }
    }

    if(el.classList && el.classList.contains('rte')){
      try{
        if(!rtSel(el)) focusEnd(el);
        rtIns(el, txt);
        return;
      }catch{}
    }

    if(typeof el.value === 'string'){
      const start = typeof el.selectionStart === 'number' ? el.selectionStart : el.value.length;
      const end = typeof el.selectionEnd === 'number' ? el.selectionEnd : el.value.length;
      if(typeof el.setRangeText === 'function'){
        el.setRangeText(txt, start, end, 'end');
      } else {
        el.value = el.value.slice(0, start) + txt + el.value.slice(end);
      }
      el.dispatchEvent(new Event('input', { bubbles: true }));
      if(el.tagName === 'TEXTAREA'){
        el.style.height = 'auto';
        el.style.height = Math.max(38, el.scrollHeight) + 'px';
      }
      try{ el.scrollIntoView({ block: 'nearest' }); }catch{}
    }
  }

  function processSpokenText(rawText){
    let text = String(rawText || '').trim();
    if(!text) return;

    // Handle natural spoken punctuation
    text = text
      .replace(/\s*(علامة استفهام|question mark)\s*/gi, '؟ ')
      .replace(/\s*(سطر جديد|new line)\s*/gi, '\n');

    // Split on "سؤال جديد" / "السؤال التالي" / "next question"
    const splitRe = /\b(?:سؤال جديد|السؤال التالي|next question)\b/gi;
    if(splitRe.test(text)){
      const segs = text.split(/\b(?:سؤال جديد|السؤال التالي|next question)\b/gi);
      segs.forEach((seg, idx)=>{
        const clean = seg.trim();
        if(clean) insertRaw(clean);
        if(idx < segs.length - 1){
          addQ('normal');
          _lastTarget = null;
          setTimeout(()=>ensureTarget(), 40);
        }
      });
      return;
    }

    insertRaw(text);
  }

  function updateMicUI(){
    const btn = document.getElementById('micbtn');
    const bar = document.getElementById('micbar');
    const live = document.getElementById('micLive');
    if(btn){
      btn.classList.toggle('on', _micOn);
      btn.setAttribute('aria-pressed', _micOn ? 'true' : 'false');
    }
    if(bar){
      bar.hidden = !_micOn;
    }
    if(live && _micOn){
      live.textContent = tr('جاري الاستماع… تحدث لكتابة السؤال');
    }
  }

  async function sendAudioBlob(blob, mimeType){
    if(!blob || blob.size < 800) return;
    const live = document.getElementById('micLive');
    if(live && _micOn) live.textContent = tr('جاري تحويل الصوت إلى نص…');
    try{
      const buf = await blob.arrayBuffer();
      const bytes = new Uint8Array(buf);
      let bin = '';
      for(let i = 0; i < bytes.length; i += 8192){
        bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 8192));
      }
      const b64 = btoa(bin);
      const r = await fetch('/api/transcribe', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
          audio: b64,
          mimeType: mimeType || 'audio/webm',
          lang: vv('f-lang') === 'en' ? 'en' : 'ar'
        })
      });
      const j = await r.json().catch(()=>null);
      if(j && j.ok && j.text){
        processSpokenText(j.text);
      }
    }catch{}finally{
      if(live && _micOn) live.textContent = tr('جاري الاستماع… تحدث لكتابة السؤال');
    }
  }

  async function startFallbackRecorder(){
    _fallbackMode = true;
    if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia || typeof MediaRecorder === 'undefined'){
      _micOn = false;
      updateMicUI();
      toast(tr('المتصفح لا يدعم الإملاء الصوتي'));
      return;
    }
    try{
      _mediaStream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mime = MediaRecorder.isTypeSupported('audio/webm;codecs=opus')
        ? 'audio/webm;codecs=opus'
        : (MediaRecorder.isTypeSupported('audio/mp4') ? 'audio/mp4' : '');
      const opts = mime ? { mimeType: mime } : {};
      const startSeg = ()=>{
        if(!_micOn || !_mediaStream) return;
        _mediaChunks = [];
        _mediaRec = new MediaRecorder(_mediaStream, opts);
        _mediaRec.ondataavailable = (ev)=>{ if(ev.data && ev.data.size > 0) _mediaChunks.push(ev.data); };
        _mediaRec.onstop = ()=>{
          const blob = new Blob(_mediaChunks, { type: _mediaRec.mimeType || 'audio/webm' });
          _mediaChunks = [];
          sendAudioBlob(blob, _mediaRec.mimeType);
          if(_micOn && _mediaStream) startSeg();
        };
        _mediaRec.start();
        clearTimeout(_chunkTimer);
        _chunkTimer = setTimeout(()=>{
          try{ if(_mediaRec && _mediaRec.state === 'recording') _mediaRec.stop(); }catch{}
        }, 4500);
      };
      startSeg();
    }catch{
      _micOn = false;
      updateMicUI();
      toast(tr('تعذر الوصول إلى الميكروفون'));
    }
  }

  function startSpeechRec(){
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if(!SR){
      startFallbackRecorder();
      return;
    }
    _fallbackMode = false;
    try{
      const rec = new SR();
      rec.continuous = true;
      rec.interimResults = true;
      rec.lang = vv('f-lang') === 'en' ? 'en-US' : 'ar-IQ';
      _committedIdx = 0;

      rec.onresult = function(ev){
        let interim = '';
        for(let i = Math.max(ev.resultIndex, _committedIdx); i < ev.results.length; i++){
          const res = ev.results[i];
          const trn = res[0] ? res[0].transcript : '';
          if(res.isFinal){
            _committedIdx = i + 1;
            processSpokenText(trn);
          } else {
            interim += trn;
          }
        }
        const live = document.getElementById('micLive');
        if(live && _micOn){
          live.textContent = interim.trim() || tr('جاري الاستماع… تحدث لكتابة السؤال');
        }
      };

      rec.onerror = function(ev){
        const err = ev && ev.error ? ev.error : '';
        if(err === 'not-allowed' || err === 'audio-capture'){
          window.stopVoiceQ();
          toast(tr('تعذر الوصول إلى الميكروفون'));
          return;
        }
        if((err === 'service-not-allowed' || err === 'network' || err === 'language-not-supported') && _micOn){
          try{ rec.abort(); }catch{}
          _rec = null;
          startFallbackRecorder();
        }
      };

      rec.onend = function(){
        if(_micOn && !_fallbackMode){
          try{ startSpeechRec(); }catch{ window.stopVoiceQ(); }
        }
      };

      _rec = rec;
      rec.start();
    }catch{
      startFallbackRecorder();
    }
  }

  window.stopVoiceQ = function(){
    _micOn = false;
    clearTimeout(_chunkTimer);
    if(_rec){
      try{ _rec.onend = null; _rec.stop(); }catch{}
      _rec = null;
    }
    if(_mediaRec){
      try{ if(_mediaRec.state === 'recording') _mediaRec.stop(); }catch{}
      _mediaRec = null;
    }
    if(_mediaStream){
      try{ _mediaStream.getTracks().forEach(t=>t.stop()); }catch{}
      _mediaStream = null;
    }
    updateMicUI();
  };

  window.togVoiceQ = function(){
    if(_micOn){
      window.stopVoiceQ();
      return;
    }
    ensureTarget();
    _micOn = true;
    updateMicUI();
    startSpeechRec();
  };

  window.voiceCmd = function(cmd){
    if(cmd === 'nl'){
      insertRaw('\n');
    } else if(cmd === 'nq'){
      addQ('normal');
      _lastTarget = null;
      setTimeout(()=>ensureTarget(), 40);
    }
  };
})();
